use std::fs

fn is_leap(y: int) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in(y: int, m: int) -> int {
    if m == 2 {
        if is_leap(y) { 29 } else { 28 }
    } else if m == 4 || m == 6 || m == 9 || m == 11 {
        30
    } else {
        31
    }
}

fn digits(s: string) -> int {
    // returns -1 if not all digits
    let mut v = 0
    if s.len() == 0 { return -1 }
    for c in s.chars() {
        if c < '0' || c > '9' { return -1 }
        v = v * 10 + (c as int - '0' as int)
    }
    v
}

// returns days since 1970-01-01 or -1000000 if invalid
fn parse(s: string) -> int {
    if s.len() != 10 { return -1000000 }
    let cs = s.chars().collect::<Vec<char>>()
    if cs[4] != '-' || cs[7] != '-' { return -1000000 }
    let y = digits(s[0..4])
    let m = digits(s[5..7])
    let d = digits(s[8..10])
    if y < 0 || m < 1 || m > 12 || d < 1 { return -1000000 }
    if d > days_in(y, m) { return -1000000 }
    let yy = if m <= 2 { y - 1 } else { y }
    let era = yy / 400
    let yoe = yy - era * 400
    let mp = (m + 9) % 12
    let doy = (153 * mp + 2) / 5 + d - 1
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy
    era * 146097 + doe - 719468
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let names = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"]
    for line in text.lines() {
        let parts = line.split_whitespace().collect::<Vec<string>>()
        if parts.len() == 0 { continue }
        if parts.len() != 2 {
            println("invalid")
            continue
        }
        let a = parse(parts[0])
        let b = parse(parts[1])
        if a == -1000000 || b == -1000000 {
            println("invalid")
            continue
        }
        let lo = if a < b { a } else { b }
        let diff = if a < b { b - a } else { a - b }
        let wd = ((lo + 4) % 7 + 7) % 7
        println("${diff} ${names[wd as usize]}")
    }
}

